arguments.cmd:
cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <meta name="description" content="Global Aid Alliance is a humanitarian nonprofit dedicated to disaster relief, emergency assistance, and community resilience worldwide." />
  <title>Global Aid Alliance — Together We Respond</title>
  <style>
    :root {
      --primary-red: oklch(46% 0.19 25);
      --primary-red-dark: oklch(40% 0.17 25);
      --primary-red-soft: oklch(91% 0.03 25);
      --navy: oklch(33% 0.08 255);
      --navy-soft: oklch(95% 0.02 255);
      --white: oklch(99% 0.003 80);
      --warm-gray-50: oklch(97% 0.004 70);
      --warm-gray-100: oklch(93% 0.006 70);
      --warm-gray-300: oklch(82% 0.01 70);
      --warm-gray-600: oklch(50% 0.012 70);
      --warm-gray-800: oklch(31% 0.01 70);
      --text-primary: oklch(26% 0.01 70);
      --text-muted: oklch(44% 0.01 70);
      --success: oklch(62% 0.15 145);
      --shadow-sm: 0 2px 10px rgba(24, 16, 16, 0.06);
      --shadow-md: 0 12px 28px rgba(24, 16, 16, 0.1);
      --radius-sm: 10px;
      --radius-md: 16px;
      --radius-lg: 24px;
      --container: 1120px;
      --transition: 220ms ease;
    }

    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      font-family: "Inter", "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
      color: var(--text-primary);
      background: var(--white);
      line-height: 1.6;
    }

    h1, h2, h3, h4 {
      margin: 0;
      font-family: "Manrope", "Inter", "Segoe UI", sans-serif;
      letter-spacing: -0.015em;
      line-height: 1.2;
      color: var(--navy);
    }

    p { margin: 0; }
    a { color: inherit; text-decoration: none; }

    .container {
      width: min(var(--container), calc(100% - 2rem));
      margin-inline: auto;
    }

    .btn {
      display: inline-flex;
      align-items: center;
      justify-content: center;
      border: 0;
      border-radius: 999px;
      padding: 0.85rem 1.35rem;
      font-weight: 700;
      cursor: pointer;
      transition: transform var(--transition), background var(--transition), box-shadow var(--transition);
      font-size: 0.98rem;
    }

    .btn:focus-visible,
    .nav-link:focus-visible,
    .icon-btn:focus-visible,
    .menu-toggle:focus-visible,
    .accordion-trigger:focus-visible {
      outline: 3px solid var(--primary-red-soft);
      outline-offset: 2px;
    }

    .btn-primary {
      background: var(--primary-red);
      color: var(--white);
      box-shadow: var(--shadow-sm);
    }

    .btn-primary:hover {
      background: var(--primary-red-dark);
      transform: translateY(-1px);
    }

    .btn-outline {
      background: transparent;
      color: var(--navy);
      border: 1.5px solid var(--navy);
    }

    .btn-outline:hover {
      background: var(--navy);
      color: var(--white);
    }

    .site-header {
      position: sticky;
      top: 0;
      z-index: 80;
      backdrop-filter: blur(8px);
      background: color-mix(in oklab, var(--white) 92%, transparent);
      border-bottom: 1px solid var(--warm-gray-100);
    }

    .header-inner {
      height: 78px;
      display: flex;
      align-items: center;
      justify-content: space-between;
      gap: 1rem;
    }

    .brand {
      display: flex;
      align-items: center;
      gap: 0.7rem;
      min-width: 0;
    }

    .brand-mark {
      width: 42px;
      height: 42px;
      border-radius: 12px;
      display: grid;
      place-items: center;
      background: linear-gradient(145deg, var(--primary-red), var(--navy));
      color: var(--white);
      font-weight: 800;
      font-size: 0.95rem;
    }

    .brand-text {
      font-weight: 800;
      color: var(--navy);
      font-size: 1.03rem;
      white-space: nowrap;
      overflow: hidden;
      text-overflow: ellipsis;
    }

    .nav-desktop {
      display: flex;
      align-items: center;
      gap: 1.15rem;
    }

    .nav-link {
      color: var(--text-primary);
      font-weight: 600;
      font-size: 0.95rem;
      position: relative;
      padding: 0.25rem 0;
    }

    .nav-link::after {
      content: "";
      position: absolute;
      left: 0;
      bottom: -0.18rem;
      width: 100%;
      height: 2px;
      transform: scaleX(0);
      transform-origin: right;
      transition: transform var(--transition);
      background: var(--primary-red);
    }

    .nav-link:hover::after,
    .nav-link[aria-current="page"]::after {
      transform: scaleX(1);
      transform-origin: left;
    }

    .mobile-controls {
      display: none;
      align-items: center;
      gap: 0.5rem;
    }

    .menu-toggle,
    .icon-btn {
      width: 42px;
      height: 42px;
      border: 0;
      border-radius: 11px;
      background: var(--warm-gray-50);
      color: var(--navy);
      display: grid;
      place-items: center;
      cursor: pointer;
      transition: background var(--transition);
    }

    .menu-toggle:hover,
    .icon-btn:hover {
      background: var(--warm-gray-100);
    }

    .hamburger {
      width: 18px;
      height: 14px;
      position: relative;
    }

    .hamburger span {
      position: absolute;
      left: 0;
      width: 100%;
      height: 2px;
      border-radius: 2px;
      background: var(--navy);
      transition: transform var(--transition), top var(--transition), opacity var(--transition);
    }

    .hamburger span:nth-child(1) { top: 0; }
    .hamburger span:nth-child(2) { top: 6px; }
    .hamburger span:nth-child(3) { top: 12px; }

    .menu-toggle[aria-expanded="true"] .hamburger span:nth-child(1) {
      top: 6px;
      transform: rotate(45deg);
    }

    .menu-toggle[aria-expanded="true"] .hamburger span:nth-child(2) {
      opacity: 0;
    }

    .menu-toggle[aria-expanded="true"] .hamburger span:nth-child(3) {
      top: 6px;
      transform: rotate(-45deg);
    }

    .mobile-drawer {
      position: fixed;
      top: 78px;
      right: 0;
      width: min(86vw, 360px);
      height: calc(100vh - 78px);
      background: var(--white);
      border-left: 1px solid var(--warm-gray-100);
      box-shadow: var(--shadow-md);
      transform: translateX(102%);
      transition: transform 280ms ease;
      z-index: 75;
      display: flex;
      flex-direction: column;
      padding: 1.15rem;
      gap: 0.75rem;
    }

    .mobile-drawer.open { transform: translateX(0); }

    .mobile-link {
      padding: 0.72rem 0.4rem;
      border-radius: 10px;
      font-weight: 600;
      color: var(--text-primary);
    }

    .mobile-link:hover { background: var(--warm-gray-50); }

    .hero {
      padding: 5.5rem 0 4rem;
      background:
        linear-gradient(120deg, color-mix(in oklab, var(--primary-red-soft) 62%, transparent), transparent 55%),
        linear-gradient(180deg, var(--warm-gray-50), var(--white));
    }

    .hero-grid {
      display: grid;
      grid-template-columns: 1.1fr 0.9fr;
      gap: 2rem;
      align-items: center;
    }

    .eyebrow {
      display: inline-flex;
      align-items: center;
      gap: 0.5rem;
      font-weight: 700;
      font-size: 0.85rem;
      padding: 0.34rem 0.72rem;
      border-radius: 999px;
      background: var(--primary-red-soft);
      color: var(--primary-red-dark);
      margin-bottom: 1.1rem;
    }

    .hero h1 {
      font-size: clamp(2rem, 4vw, 3.35rem);
      margin-bottom: 1rem;
    }

    .hero p {
      color: var(--text-muted);
      font-size: clamp(1rem, 2vw, 1.18rem);
      max-width: 58ch;
      margin-bottom: 1.5rem;
    }

    .hero-actions {
      display: flex;
      flex-wrap: wrap;
      gap: 0.8rem;
      margin-bottom: 1.4rem;
    }

    .hero-note {
      font-size: 0.9rem;
      color: var(--text-muted);
      display: flex;
      align-items: center;
      gap: 0.45rem;
    }

    .hero-card {
      border-radius: var(--radius-lg);
      overflow: hidden;
      box-shadow: var(--shadow-md);
      border: 1px solid var(--warm-gray-100);
      background: var(--white);
    }

    .hero-card img {
      width: 100%;
      height: 100%;
      min-height: 340px;
      object-fit: cover;
      display: block;
    }

    section { padding: 4.4rem 0; }

    .section-title {
      font-size: clamp(1.65rem, 2.8vw, 2.3rem);
      margin-bottom: 0.8rem;
    }

    .section-subtitle {
      color: var(--text-muted);
      max-width: 72ch;
      margin-bottom: 2rem;
    }

    .mission-grid {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 1.25rem;
    }

    .panel {
      background: var(--warm-gray-50);
      border: 1px solid var(--warm-gray-100);
      border-radius: var(--radius-md);
      padding: 1.2rem;
    }

    .panel h3 {
      margin-bottom: 0.55rem;
      font-size: 1.15rem;
    }

    .stats-wrap {
      background: var(--navy);
      color: var(--white);
      border-radius: var(--radius-lg);
      padding: 2.2rem 1.2rem;
    }

    .stats-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 0.9rem;
    }

    .stat-card {
      border: 1px solid color-mix(in oklab, var(--white) 16%, transparent);
      border-radius: var(--radius-md);
      padding: 1.2rem 1rem;
      background: color-mix(in oklab, var(--white) 6%, transparent);
      text-align: center;
    }

    .stat-value {
      display: block;
      font-size: clamp(1.6rem, 3.2vw, 2.25rem);
      font-weight: 800;
      margin-bottom: 0.3rem;
      color: var(--white);
    }

    .stat-label {
      font-size: 0.95rem;
      color: color-mix(in oklab, var(--white) 80%, var(--navy));
    }

    .accordion {
      display: grid;
      gap: 0.7rem;
    }

    .accordion-item {
      border: 1px solid var(--warm-gray-100);
      border-radius: var(--radius-sm);
      overflow: hidden;
      background: var(--white);
    }

    .accordion-trigger {
      width: 100%;
      border: 0;
      background: var(--white);
      color: var(--navy);
      text-align: left;
      font: inherit;
      font-weight: 700;
      padding: 1rem 1.1rem;
      cursor: pointer;
      display: flex;
      align-items: center;
      justify-content: space-between;
    }

    .accordion-trigger:hover {
      background: var(--warm-gray-50);
    }

    .accordion-icon {
      width: 20px;
      height: 20px;
      border-radius: 50%;
      border: 1px solid var(--warm-gray-300);
      display: grid;
      place-items: center;
      font-size: 0.95rem;
      line-height: 1;
      transition: transform var(--transition);
    }

    .accordion-content {
      max-height: 0;
      overflow: hidden;
      transition: max-height 280ms ease;
      background: var(--warm-gray-50);
    }

    .accordion-inner {
      padding: 0 1.1rem 1rem;
      color: var(--text-muted);
    }

    .accordion-item.open .accordion-content { max-height: 280px; }
    .accordion-item.open .accordion-icon { transform: rotate(45deg); }

    .involved-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 1rem;
    }

    .involved-card {
      padding: 1.2rem;
      border: 1px solid var(--warm-gray-100);
      border-radius: var(--radius-md);
      background: var(--white);
      box-shadow: var(--shadow-sm);
    }

    .involved-card h3 { margin-bottom: 0.45rem; }
    .involved-card p { color: var(--text-muted); margin-bottom: 1rem; }

    .news-area {
      background: var(--warm-gray-50);
    }

    .news-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 1rem;
      margin-bottom: 1.2rem;
    }

    .carousel-controls {
      display: flex;
      gap: 0.5rem;
    }

    .news-track-wrap {
      overflow: hidden;
      border-radius: var(--radius-md);
    }

    .news-track {
      display: flex;
      transition: transform 360ms ease;
      will-change: transform;
    }

    .news-card {
      flex: 0 0 calc(100% / 3);
      padding: 0.55rem;
    }

    .news-card-inner {
      height: 100%;
      border-radius: var(--radius-md);
      border: 1px solid var(--warm-gray-100);
      background: var(--white);
      overflow: hidden;
      box-shadow: var(--shadow-sm);
    }

    .news-card img {
      width: 100%;
      height: 170px;
      object-fit: cover;
      display: block;
    }

    .news-content {
      padding: 1rem;
    }

    .news-date {
      font-size: 0.8rem;
      font-weight: 700;
      color: var(--primary-red-dark);
      text-transform: uppercase;
      letter-spacing: 0.06em;
      margin-bottom: 0.5rem;
    }

    .news-content h3 {
      font-size: 1.06rem;
      margin-bottom: 0.45rem;
    }

    .news-content p {
      color: var(--text-muted);
      font-size: 0.95rem;
    }

    .donate-cta {
      background: linear-gradient(120deg, var(--navy), color-mix(in oklab, var(--navy) 76%, black));
      color: var(--white);
      border-radius: var(--radius-lg);
      padding: 2.2rem;
      display: grid;
      grid-template-columns: 1.1fr auto;
      gap: 1.2rem;
      align-items: center;
    }

    .donate-cta h2 { color: var(--white); margin-bottom: 0.55rem; }
    .donate-cta p { color: color-mix(in oklab, var(--white) 80%, var(--navy)); }

    .footer {
      margin-top: 4.5rem;
      background: var(--warm-gray-50);
      border-top: 1px solid var(--warm-gray-100);
      padding: 3rem 0 2rem;
    }

    .footer-grid {
      display: grid;
      grid-template-columns: 1.2fr repeat(4, 1fr);
      gap: 1rem;
    }

    .footer h4 {
      font-size: 0.95rem;
      margin-bottom: 0.6rem;
      color: var(--navy);
    }

    .footer-links a {
      display: block;
      color: var(--text-muted);
      margin-bottom: 0.42rem;
      font-size: 0.92rem;
    }

    .footer-links a:hover { color: var(--primary-red-dark); }

    .footer-meta {
      margin-top: 1.5rem;
      padding-top: 1rem;
      border-top: 1px solid var(--warm-gray-100);
      color: var(--text-muted);
      font-size: 0.88rem;
      display: flex;
      flex-wrap: wrap;
      justify-content: space-between;
      gap: 0.6rem;
    }

    .modal {
      position: fixed;
      inset: 0;
      background: rgba(15, 18, 30, 0.56);
      display: none;
      align-items: center;
      justify-content: center;
      z-index: 120;
      padding: 1rem;
    }

    .modal.open { display: flex; }

    .modal-card {
      width: min(560px, 100%);
      background: var(--white);
      border-radius: var(--radius-md);
      padding: 1.25rem;
      border: 1px solid var(--warm-gray-100);
      box-shadow: var(--shadow-md);
    }

    .modal-header {
      display: flex;
      justify-content: space-between;
      align-items: center;
      gap: 0.7rem;
      margin-bottom: 0.85rem;
    }

    .amount-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 0.6rem;
      margin: 1rem 0;
    }

    .amount-btn {
      border: 1px solid var(--warm-gray-300);
      background: var(--white);
      border-radius: 12px;
      padding: 0.8rem;
      font-weight: 700;
      cursor: pointer;
    }

    .amount-btn.active {
      border-color: var(--primary-red);
      background: var(--primary-red-soft);
      color: var(--primary-red-dark);
    }

    .donate-summary {
      padding: 0.75rem;
      border-radius: 11px;
      background: var(--warm-gray-50);
      color: var(--text-muted);
      margin-bottom: 0.9rem;
      font-size: 0.92rem;
    }

    @media (max-width: 980px) {
      .nav-desktop, .desktop-donate { display: none; }
      .mobile-controls { display: flex; }
      .hero-grid, .mission-grid, .donate-cta, .footer-grid { grid-template-columns: 1fr; }
      .stats-grid { grid-template-columns: repeat(2, 1fr); }
      .involved-grid { grid-template-columns: 1fr 1fr; }
      .news-card { flex-basis: 50%; }
      .hero { padding-top: 4.7rem; }
    }

    @media (max-width: 680px) {
      .container { width: min(var(--container), calc(100% - 1.25rem)); }
      section { padding: 3.4rem 0; }
      .stats-grid,
      .involved-grid,
      .amount-grid { grid-template-columns: 1fr; }
      .news-card { flex-basis: 100%; }
      .hero-card img { min-height: 280px; }
    }

    @media (prefers-reduced-motion: reduce) {
      *, *::before, *::after { animation: none !important; transition: none !important; }
      html { scroll-behavior: auto; }
    }
  </style>
</head>
<body>
  <header class="site-header" id="top">
    <div class="container header-inner">
      <a class="brand" href="#top" aria-label="Global Aid Alliance home">
        <span class="brand-mark" aria-hidden="true">GAA</span>
        <span class="brand-text">Global Aid Alliance</span>
      </a>

      <nav class="nav-desktop" aria-label="Main navigation">
        <a class="nav-link" href="#mission">About Us</a>
        <a class="nav-link" href="#programs">Disaster Relief</a>
        <a class="nav-link" href="#get-involved">Volunteer</a>
        <a class="nav-link" href="#news">News</a>
        <a class="nav-link" href="#footer">Find Local Chapter</a>
      </nav>

      <button class="btn btn-primary desktop-donate" data-open-donate>Donate</button>

      <div class="mobile-controls">
        <button class="btn btn-primary" data-open-donate aria-label="Donate">Donate</button>
        <button class="menu-toggle" aria-label="Open menu" aria-expanded="false" aria-controls="mobile-drawer">
          <span class="hamburger" aria-hidden="true"><span></span><span></span><span></span></span>
        </button>
      </div>
    </div>
  </header>

  <aside class="mobile-drawer" id="mobile-drawer" aria-label="Mobile navigation">
    <a class="mobile-link" href="#mission">About Us</a>
    <a class="mobile-link" href="#programs">Disaster Relief</a>
    <a class="mobile-link" href="#get-involved">Volunteer</a>
    <a class="mobile-link" href="#news">News</a>
    <a class="mobile-link" href="#footer">Find Local Chapter</a>
    <button class="btn btn-primary" data-open-donate>Donate Now</button>
  </aside>

  <main>
    <section class="hero" id="hero">
      <div class="container hero-grid">
        <div>
          <span class="eyebrow">Humanitarian Relief · Worldwide</span>
          <h1>Together We Respond, Together We Rebuild.</h1>
          <p>
            Global Aid Alliance delivers rapid disaster response, lifesaving supplies, and long-term resilience programs in communities facing crisis.
            We serve with speed, dignity, and global solidarity.
          </p>
          <div class="hero-actions">
            <button class="btn btn-primary" data-open-donate>Donate Now</button>
            <a class="btn btn-outline" href="#get-involved">Become a Volunteer</a>
          </div>
          <div class="hero-note" aria-label="Trust statement">
            <span aria-hidden="true">●</span>
            91¢ of every $1 supports humanitarian services.
          </div>
        </div>

        <figure class="hero-card">
          <img src="https://images.unsplash.com/photo-1593113598332-cd59a93f7ddd?auto=format&fit=crop&w=1200&q=80"
               alt="Relief workers distributing emergency supplies to diverse families after a disaster" loading="lazy" />
        </figure>
      </div>
    </section>

    <section id="mission">
      <div class="container">
        <h2 class="section-title">Mission & Approach</h2>
        <p class="section-subtitle">We help communities prepare for, survive, and recover from disasters through coordinated emergency aid, trained local volunteers, and equitable long-term support systems.</p>
        <div class="mission-grid">
          <article class="panel">
            <h3>Our Mission</h3>
            <p>Prevent and alleviate human suffering in the face of emergencies by mobilizing people, resources, and partnerships where they are needed most.</p>
          </article>
          <article class="panel">
            <h3>Our Values</h3>
            <p>Humanity, impartiality, accountability, and local partnership guide every response operation from first alert through full recovery.</p>
          </article>
        </div>
      </div>
    </section>

    <section id="impact-stats">
      <div class="container stats-wrap">
        <h2 class="section-title" style="color: var(--white); margin-bottom: 1.5rem; text-align:center;">Global Impact at a Glance</h2>
        <div class="stats-grid">
          <article class="stat-card">
            <span class="stat-value" data-counter="12000000" data-prefix="" data-suffix="M">0</span>
            <span class="stat-label">People Helped</span>
          </article>
          <article class="stat-card">
            <span class="stat-value" data-counter="50000" data-prefix="" data-suffix="K+">0</span>
            <span class="stat-label">Volunteers Mobilized</span>
          </article>
          <article class="stat-card">
            <span class="stat-value" data-counter="190" data-prefix="" data-suffix="">0</span>
            <span class="stat-label">Countries Served</span>
          </article>
          <article class="stat-card">
            <span class="stat-value" data-counter="850000000" data-prefix="$" data-suffix="M">0</span>
            <span class="stat-label">Raised for Relief</span>
          </article>
        </div>
      </div>
    </section>

    <section id="programs">
      <div class="container">
        <h2 class="section-title">Programs & Services</h2>
        <p class="section-subtitle">From immediate response to long-term resilience, our core programs support disaster-affected communities before, during, and after emergencies.</p>
        <div class="accordion" role="list">
          <article class="accordion-item open" role="listitem">
            <button class="accordion-trigger" aria-expanded="true">Disaster Relief <span class="accordion-icon" aria-hidden="true">+</span></button>
            <div class="accordion-content">
              <div class="accordion-inner">Rapid emergency deployment of shelters, medical support, food, clean water, and logistics coordination after hurricanes, floods, earthquakes, and conflict-related displacement.</div>
            </div>
          </article>
          <article class="accordion-item" role="listitem">
            <button class="accordion-trigger" aria-expanded="false">Blood Donation <span class="accordion-icon" aria-hidden="true">+</span></button>
            <div class="accordion-content">
