  <script>
    const menuToggle = document.querySelector('.menu-toggle');
    const mobileDrawer = document.getElementById('mobile-drawer');

    menuToggle?.addEventListener('click', () => {
      const expanded = menuToggle.getAttribute('aria-expanded') === 'true';
      menuToggle.setAttribute('aria-expanded', String(!expanded));
      mobileDrawer.classList.toggle('open', !expanded);
    });

    mobileDrawer?.querySelectorAll('a, button').forEach((item) => {
      item.addEventListener('click', () => {
        mobileDrawer.classList.remove('open');
        menuToggle?.setAttribute('aria-expanded', 'false');
      });
    });

    const donateModal = document.getElementById('donate-modal');
    const closeModalButton = document.getElementById('close-modal');
    const openDonateButtons = document.querySelectorAll('[data-open-donate]');

    const openModal = () => {
      donateModal.classList.add('open');
      donateModal.setAttribute('aria-hidden', 'false');
      document.body.style.overflow = 'hidden';
    };

    const closeModal = () => {
      donateModal.classList.remove('open');
      donateModal.setAttribute('aria-hidden', 'true');
      document.body.style.overflow = '';
    };

    openDonateButtons.forEach((button) => button.addEventListener('click', openModal));
    closeModalButton?.addEventListener('click', closeModal);

    donateModal?.addEventListener('click', (event) => {
      if (event.target === donateModal) closeModal();
    });

    document.addEventListener('keydown', (event) => {
      if (event.key === 'Escape' && donateModal.classList.contains('open')) closeModal();
    });

    const amountDescriptions = {
      '25': '$25 provides 5 emergency blankets for displaced families.',
      '50': '$50 supplies a family with food and water for one week.',
      '100': '$100 funds emergency shelter materials for a household.',
      '250': '$250 equips a volunteer with disaster response training.',
      '500': '$500 supports rapid-response medical and logistics kits.',
      'custom': 'Every dollar counts toward saving lives.'
    };

    const amountButtons = document.querySelectorAll('.amount-btn');
    const donateSummary = document.getElementById('donate-summary');

    amountButtons.forEach((button) => {
      button.addEventListener('click', () => {
        amountButtons.forEach((item) => item.classList.remove('active'));
        button.classList.add('active');
        donateSummary.textContent = amountDescriptions[button.dataset.amount] || 'Every dollar counts toward saving lives.';
      });
    });

    const accordionItems = document.querySelectorAll('.accordion-item');
    accordionItems.forEach((item) => {
      const trigger = item.querySelector('.accordion-trigger');
      trigger.addEventListener('click', () => {
        const isOpen = item.classList.contains('open');
        accordionItems.forEach((entry) => {
          entry.classList.remove('open');
          entry.querySelector('.accordion-trigger').setAttribute('aria-expanded', 'false');
        });
        if (!isOpen) {
          item.classList.add('open');
          trigger.setAttribute('aria-expanded', 'true');
        }
      });
    });

    const counters = document.querySelectorAll('[data-counter]');
    const counterObserver = new IntersectionObserver((entries) => {
      entries.forEach((entry) => {
        if (!entry.isIntersecting) return;
        const el = entry.target;
        const target = Number(el.dataset.counter);
        const prefix = el.dataset.prefix || '';
        const suffix = el.dataset.suffix || '';
        const duration = 1400;
        const start = performance.now();

        const formatValue = (value) => {
          if (suffix === 'M') return `${prefix}${(value / 1000000).toFixed(value >= 10000000 ? 0 : 1)}M`;
          if (suffix === 'K+') return `${prefix}${Math.round(value / 1000)}K+`;
          return `${prefix}${Math.round(value)}${suffix}`;
        };

        const animate = (now) => {
          const progress = Math.min((now - start) / duration, 1);
          const eased = 1 - Math.pow(1 - progress, 3);
          el.textContent = formatValue(target * eased);
          if (progress < 1) requestAnimationFrame(animate);
        };

        requestAnimationFrame(animate);
        counterObserver.unobserve(el);
      });
    }, { threshold: 0.35 });

    counters.forEach((counter) => counterObserver.observe(counter));

    const newsTrack = document.getElementById('news-track');
    const prevButton = document.getElementById('news-prev');
    const nextButton = document.getElementById('news-next');
    const newsCards = Array.from(newsTrack.children);
    let currentIndex = 0;

    const getVisibleCards = () => {
      if (window.innerWidth <= 680) return 1;
      if (window.innerWidth <= 980) return 2;
      return 3;
    };

    const updateCarousel = () => {
      const visible = getVisibleCards();
      const maxIndex = Math.max(0, newsCards.length - visible);
      currentIndex = Math.min(currentIndex, maxIndex);
      const offsetPercentage = (100 / visible) * currentIndex;
      newsTrack.style.transform = `translateX(-${offsetPercentage}%)`;
      prevButton.disabled = currentIndex <= 0;
      nextButton.disabled = currentIndex >= maxIndex;
      prevButton.style.opacity = prevButton.disabled ? '0.5' : '1';
      nextButton.style.opacity = nextButton.disabled ? '0.5' : '1';
    };

    prevButton.addEventListener('click', () => {
      currentIndex -= 1;
      updateCarousel();
    });

    nextButton.addEventListener('click', () => {
      currentIndex += 1;
      updateCarousel();
    });

    window.addEventListener('resize', updateCarousel);
    updateCarousel();
  </script>
</body>
</html>
